let p = msg.payload;
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch (e) { return null; }
}
if (!p || typeof p !== 'object') return null;
const dev = (p.devices && p.devices.conveyor) ? p.devices.conveyor : {};
const online = dev.online ? 'в сети' : 'не в сети';
const proto = dev.kind_ok ? 'норма' : 'ошибка';
msg.payload = `Конвейер: ${online} | протокол=${proto} | статус=${dev.status_word ?? '-'} | ошибка=${dev.error_word ?? '-'} | флаг=${dev.flag_state ?? '-'} | движение=${dev.motion_state ?? '-'}`;
return msg;

let p = msg.payload;
if (typeof p === "string") {
  try { p = JSON.parse(p); } catch (e) { return null; }
}
if (!p || typeof p !== "object") return null;

const wifiState = p.wifi ? "\u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d" : "\u043d\u0435\u0442";
const ip = p.ip ? p.ip : "-";
const modbusId = (p.modbus_id !== undefined) ? p.modbus_id : "-";
const req = (p.mb_req !== undefined) ? p.mb_req : 0;
const ok = (p.mb_ok !== undefined) ? p.mb_ok : 0;
const err = (p.mb_err !== undefined) ? p.mb_err : 0;
const baseHz = (p.vfd_base_hz !== undefined) ? Number(p.vfd_base_hz).toFixed(2) : "0.00";
const cmdSeq = (p.cmd_seq !== undefined) ? p.cmd_seq : 0;
const lastCmd = p.last_cmd ? p.last_cmd : "-";

const wifi = `Wi-Fi: ${wifiState} | IP: ${ip}`;
const mb = `ID=${modbusId} | req=${req} | ok=${ok} | err=${err}`;
const vfd = `\u0411\u0430\u0437\u043e\u0432\u0430\u044f \u0447\u0430\u0441\u0442\u043e\u0442\u0430: ${baseHz} \u0413\u0446`;
const last = `\u041a\u043e\u043c\u0430\u043d\u0434\u0430 #${cmdSeq}: ${lastCmd}`;

return [{ payload: wifi }, { payload: mb }, { payload: vfd }, { payload: last }];

let p = msg.payload;
if (typeof p === "string") {
  try { p = JSON.parse(p); } catch (e) {
    return { payload: `Ответ: ${msg.payload}` };
  }
}
if (!p || typeof p !== "object") {
  return { payload: "Ответ: некорректный формат" };
}
const seq = (p.seq !== undefined) ? p.seq : "-";
const cmd = p.cmd ? p.cmd : "-";
const accepted = !!p.accepted;
const result = p.result ? p.result : "-";
const state = accepted ? "ОК" : "ОШИБКА";
msg.payload = `#${seq} | ${state} | ${cmd} | ${result}`;
return msg;

let p = msg.payload;
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch (e) { return null; }
}
if (!p || typeof p !== 'object') return null;
const devices = p.devices || {};
const vfd = devices.vfd || {};
const conveyor = devices.conveyor || {};
const manipulator = devices.manipulator || {};
const vfdLine = `ПЧ: ${vfd.online ? 'в сети' : 'не в сети'} | статус=${vfd.status_word ?? '-'} | частота=${vfd.run_hz ?? 0} Гц | авария=${vfd.fault ?? 0}`;
const conveyorLine = `Конвейер: ${conveyor.online ? 'в сети' : 'не в сети'} | протокол=${conveyor.kind_ok ? 'норма' : 'ошибка'} | статус=${conveyor.status_word ?? '-'} | ошибка=${conveyor.error_word ?? '-'} | флаг=${conveyor.flag_state ?? '-'} | движение=${conveyor.motion_state ?? '-'}`;
const manipulatorLine = `Манипулятор: ${manipulator.online ? 'в сети' : 'не в сети'} | протокол=${manipulator.kind_ok ? 'норма' : 'ошибка'} | статус=${manipulator.status_word ?? '-'} | ошибка=${manipulator.error_word ?? '-'} | режим=${manipulator.mode ?? '-'} | задача=${manipulator.job ?? '-'} | датчики=${manipulator.sensor_bits ?? '-'} | конфликты=${manipulator.conflict_bits ?? '-'}`;
return [{ payload: vfdLine }, { payload: conveyorLine }, { payload: manipulatorLine }];

let p = msg.payload;
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch (e) { return null; }
}
if (!p || typeof p !== 'object') return null;
const dev = (p.devices && p.devices.manipulator) ? p.devices.manipulator : {};
const online = dev.online ? 'в сети' : 'не в сети';
const proto = dev.kind_ok ? 'норма' : 'ошибка';
msg.payload = `Манипулятор: ${online} | протокол=${proto} | статус=${dev.status_word ?? '-'} | ошибка=${dev.error_word ?? '-'} | режим=${dev.mode ?? '-'} | задача=${dev.job ?? '-'} | датчики=${dev.sensor_bits ?? '-'} | конфликты=${dev.conflict_bits ?? '-'}`;
return msg;

const payload = msg.payload;
if (typeof payload === 'string') {
    return msg;
}
const data = (payload && typeof payload === 'object') ? payload : {};
const action = String(data.action || '').trim().toLowerCase();
const rawSteps = Number(data.steps);
const rawCm = Number(data.cm);
const steps = Number.isFinite(rawSteps) && rawSteps > 0 ? Math.round(rawSteps) : 920;
const cm = Number.isFinite(rawCm) && rawCm > 0 ? Math.round(rawCm * 10) / 10 : 43;
const cmToken = Number.isInteger(cm) ? String(cm) : cm.toFixed(1);
const otvodMsg = { payload: `CONV OTVOD ${steps}` };
const vfdMsg = { payload: 'CONV VFDTICK RUN' };
const seqMsg = { payload: `OTCYCLE START 1 ${steps} ${cmToken}` };
const cycleMsg = { payload: `OTCYCLE START 3 ${steps} ${cmToken}` };
if (action === 'otvod') {
    return otvodMsg;
}
if (action === 'vfd') {
    return vfdMsg;
}
if (action === 'sequence') {
    node.status({ fill: 'yellow', shape: 'dot', text: seqMsg.payload });
    return seqMsg;
}
if (action === 'cycle3') {
    node.status({ fill: 'green', shape: 'dot', text: cycleMsg.payload });
    return cycleMsg;
}
node.status({ fill: 'red', shape: 'ring', text: 'unknown action' });
return null;

const OFFLINE_AFTER_MS = 7000;

let p = msg.payload;
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch (e) { return null; }
}
if (!p || typeof p !== 'object') {
  return null;
}

function buildView(src, online) {
  let state = 'Нет связи';
  let color = '#9e9e9e';

  if (online && src.start_out) {
    state = 'Импульс пуска';
    color = '#ff9800';
  } else if (online && src.cycle_running) {
    state = 'Цикл идет';
    color = '#1e88e5';
  } else if (online && src.done_active) {
    state = 'Цикл завершен';
    color = '#43a047';
  } else if (online) {
    state = 'Готов';
    color = '#90a4ae';
  }

  return {
    online: online,
    online_text: online ? 'В сети' : 'Не в сети',
    state: state,
    color: color,
    ip: src.ip || '-',
    fw: src.fw || '-',
    start_out: !!src.start_out,
    done_active: !!src.done_active,
    cycle_running: !!src.cycle_running,
    done_count: Number(src.done_count || 0),
    last_result: src.last_result || '-'
  };
}

const source = {
  ip: p.ip || '-',
  fw: p.fw || '-',
  start_out: !!p.start_out,
  done_active: !!p.done_active,
  cycle_running: !!p.cycle_running,
  done_count: Number(p.done_count || 0),
  last_result: p.last_result || '-'
};

const prevTimer = context.get('offlineTimer');
if (prevTimer) {
  clearTimeout(prevTimer);
}

const offlinePayload = buildView(source, false);
const timer = setTimeout(() => {
  node.send({ payload: offlinePayload });
}, OFFLINE_AFTER_MS);

context.set('offlineTimer', timer);
msg.payload = buildView(source, true);
return msg;

finalize:
const timer = context.get('offlineTimer');
if (timer) {
  clearTimeout(timer);
  context.set('offlineTimer', null);
}

