const LOG_LIMIT = 80;

function parsePayload(src) {
    if (typeof src === 'string') {
        try {
            return JSON.parse(src);
        } catch (e) {
            return null;
        }
    }
    return (src && typeof src === 'object') ? src : null;
}

function stageLabel(stage) {
    switch (String(stage || 'idle')) {
        case 'wait_initial_batch': return 'Ждем первую партию';
        case 'wait_manip_ready': return 'Готовим манипулятор';
        case 'wait_manip_step7': return 'Манипулятор идет к шагу 7';
        case 'wait_next_batch': return 'Ждем новую партию и окончание параллельных процессов';
        case 'idle': return 'Ожидание';
        default: return stage || 'Ожидание';
    }
}

function yesNo(value, yes = 'да', no = 'нет') {
    return value ? yes : no;
}

function onlineText(value) {
    return value ? 'в сети' : 'нет связи';
}

function pushLog(lines, text) {
    const line = String(text || '').trim();
    if (!line) {
        return;
    }
    const stamp = new Date().toLocaleTimeString('ru-RU', { hour12: false });
    const entry = `[${stamp}] ${line}`;
    if (lines[lines.length - 1] !== entry) {
        lines.push(entry);
    }
    while (lines.length > LOG_LIMIT) {
        lines.shift();
    }
}

let logs = context.get('commonCycleLogs') || [];
let snapshot = context.get('commonCycleSnapshot') || null;

const payload = msg.payload;
if (payload && typeof payload === 'object' && payload.action === 'clear_log') {
    logs = [];
    context.set('commonCycleLogs', logs);
    return [null, { payload: { text: 'Лог очищен.', count: 0 } }];
}

if (msg.topic === 'fyl/master_com12/resp') {
    const resp = parsePayload(payload);
    if (!resp) {
        return null;
    }
    const state = resp.accepted ? 'OK' : 'ОШИБКА';
    pushLog(logs, `Команда #${resp.seq ?? '-'}: ${resp.cmd || '-'} -> ${state} | ${resp.result || '-'}`);
    context.set('commonCycleLogs', logs);
    return [null, { payload: { text: logs.slice().reverse().join('\n'), count: logs.length } }];
}

const p = parsePayload(payload);
if (!p) {
    return null;
}

const cc = p.common_cycle || {};
const ot = p.otvod_cycle || {};
const seal = p.seal || {};
const devices = p.devices || {};
const conv = devices.conveyor || {};
const man = devices.manipulator || {};
const vfd = devices.vfd || {};

if (!snapshot) {
    pushLog(logs, 'Монитор общего цикла подключен.');
}

if (!snapshot || !!cc.active !== snapshot.ccActive) {
    pushLog(logs, cc.active ? 'Общий цикл активен.' : 'Общий цикл остановлен.');
}
if (!snapshot || !!cc.pause !== snapshot.ccPause) {
    if (cc.pause) {
        pushLog(logs, 'Общий цикл: запрошена мягкая пауза.');
    } else if (snapshot) {
        pushLog(logs, 'Общий цикл: пауза снята.');
    }
}
if (!snapshot || String(cc.stage || 'idle') !== snapshot.ccStage) {
    pushLog(logs, `Этап общего цикла: ${stageLabel(cc.stage)}`);
}
if (cc.last && (!snapshot || cc.last !== snapshot.ccLast) && cc.last !== 'idle') {
    pushLog(logs, cc.last);
}
if (!snapshot || !!conv.online !== snapshot.convOnline) {
    pushLog(logs, `Конвейер: ${onlineText(!!conv.online)}.`);
}
if (!snapshot || !!man.online !== snapshot.manOnline) {
    pushLog(logs, `Манипулятор: ${onlineText(!!man.online)}.`);
}
if (!snapshot || !!vfd.online !== snapshot.vfdOnline) {
    pushLog(logs, `Основной отводной / ПЧ: ${onlineText(!!vfd.online)}.`);
}
if ((!snapshot || Number(conv.batch_seq || 0) !== snapshot.batchSeq) && Number(conv.batch_seq || 0) > 0) {
    pushLog(logs, `Подводной: готова партия #${conv.batch_seq}.`);
}
if ((!snapshot || !!conv.batch_ready !== snapshot.batchReady) && !!conv.batch_ready) {
    pushLog(logs, 'Подводной: партия готова для манипулятора.');
}
if ((!snapshot || Number(man.work_step || 0) !== snapshot.manStep) && Number(man.work_step || 0) > 0) {
    pushLog(logs, `Манипулятор: шаг ${man.work_step}.`);
}
if ((!snapshot || !!man.step7_ready !== snapshot.step7Ready) && !!man.step7_ready) {
    pushLog(logs, 'Манипулятор: достигнут шаг 7.');
}
if (ot.last && (!snapshot || ot.last !== snapshot.otLast) && ot.last !== 'idle') {
    pushLog(logs, ot.last);
}
if ((!snapshot || !!seal.start_out !== snapshot.sealStart) && !!seal.start_out) {
    pushLog(logs, 'Запайщик: импульс пуска подан.');
}
if ((!snapshot || !!seal.done !== snapshot.sealDone) && !!seal.done) {
    pushLog(logs, 'Запайщик: цикл завершен.');
}

snapshot = {
    ccActive: !!cc.active,
    ccPause: !!cc.pause,
    ccStage: String(cc.stage || 'idle'),
    ccLast: String(cc.last || ''),
    convOnline: !!conv.online,
    manOnline: !!man.online,
    vfdOnline: !!vfd.online,
    batchSeq: Number(conv.batch_seq || 0),
    batchReady: !!conv.batch_ready,
    manStep: Number(man.work_step || 0),
    step7Ready: !!man.step7_ready,
    otLast: String(ot.last || ''),
    sealStart: !!seal.start_out,
    sealDone: !!seal.done
};
context.set('commonCycleSnapshot', snapshot);
context.set('commonCycleLogs', logs);

const state = cc.active ? (cc.pause ? 'Пауза после безопасной точки' : 'Общий цикл активен') : 'Остановлен';
const color = cc.active ? (cc.pause ? '#ef6c00' : '#2e7d32') : '#90a4ae';

return [
    {
        payload: {
            state,
            color,
            stage: stageLabel(cc.stage),
            last: cc.last || '-',
            wifi: yesNo(!!p.wifi, 'подключен', 'нет'),
            ip: p.ip || '-',
            conveyor: onlineText(!!conv.online),
            manipulator: onlineText(!!man.online),
            vfd: onlineText(!!vfd.online),
            batch_seq: Number(conv.batch_seq || 0),
            batch_ready: yesNo(!!conv.batch_ready),
            program_state: Number(conv.program_state || 0),
            program_pass: Number(conv.program_pass || 0),
            manip_step: Number(man.work_step || 0),
            step7_ready: yesNo(!!man.step7_ready),
            ot_active: yesNo(!!ot.active),
            ot_ready: yesNo(!!ot.ready),
            ot_step_done: Number(ot.step_done || 0),
            ot_vfd_done: Number(ot.vfd_done || 0),
            seal_start: yesNo(!!seal.start_out),
            seal_done: yesNo(!!seal.done),
            manip_starts: Number(cc.manip_starts || 0),
            parallel_starts: Number(cc.parallel_starts || 0)
        }
    },
    {
        payload: {
            text: logs.slice().reverse().join('\n'),
            count: logs.length
        }
    }
];

const OVERRIDE_META = {
    ok: { label: 'Норма', color: '#2e7d32' },
    warn: { label: 'Внимание', color: '#f9a825' },
    stop: { label: 'Стоп', color: '#d32f2f' },
    pause: { label: 'Пауза', color: '#ef6c00' }
};

function parsePayload(src) {
    if (typeof src === 'string') {
        try {
            return JSON.parse(src);
        } catch (e) {
            return null;
        }
    }
    return (src && typeof src === 'object') ? src : null;
}

function stageLabel(stage) {
    switch (String(stage || 'idle')) {
        case 'wait_initial_batch': return 'Ждем первую партию';
        case 'wait_manip_ready': return 'Готовим манипулятор';
        case 'wait_manip_step7': return 'Манипулятор идет к шагу 7';
        case 'wait_next_batch': return 'Ждем новую партию и окончание параллельных процессов';
        case 'idle': return 'Ожидание';
        default: return stage || 'Ожидание';
    }
}

let overrides = context.get('sectionOverrides') || {};
let lastStatus = context.get('sectionLastStatus') || null;

const payload = msg.payload;
if (msg.topic === 'fyl/master_com12/status') {
    const parsed = parsePayload(payload);
    if (!parsed) {
        return null;
    }
    lastStatus = parsed;
    context.set('sectionLastStatus', lastStatus);
} else if (payload && typeof payload === 'object' && payload.action === 'set_section') {
    const section = String(payload.section || '').trim();
    const state = String(payload.state || 'auto').trim().toLowerCase();
    const note = String(payload.note || '').trim();
    if (!section) {
        return null;
    }
    if (state === 'auto') {
        delete overrides[section];
    } else {
        overrides[section] = {
            state,
            note,
            updatedAt: new Date().toISOString()
        };
    }
    context.set('sectionOverrides', overrides);
} else {
    return null;
}

if (!lastStatus) {
    return null;
}

const cc = lastStatus.common_cycle || {};
const ot = lastStatus.otvod_cycle || {};
const seal = lastStatus.seal || {};
const devices = lastStatus.devices || {};
const conv = devices.conveyor || {};
const man = devices.manipulator || {};
const vfd = devices.vfd || {};

function buildSection(id, title, short, actualState, detail, color) {
    const override = overrides[id];
    const section = {
        id,
        title,
        short,
        actual_state: actualState,
        state: actualState,
        detail,
        color,
        mode: 'auto',
        note: ''
    };
    if (override && OVERRIDE_META[override.state]) {
        section.state = OVERRIDE_META[override.state].label;
        section.color = OVERRIDE_META[override.state].color;
        section.mode = 'manual';
        section.note = override.note || '';
    }
    return section;
}

const commonFailed = /failed|timeout|error/i.test(String(cc.last || ''));
const conveyorOnline = !!conv.online;
const manipOnline = !!man.online;
const vfdOnline = !!vfd.online;
const otFailed = /failed|timeout/i.test(String(ot.last || ''));
const vfdRunHz = Number(vfd.run_hz || 0);

const sections = [
    buildSection(
        'common',
        'Общий цикл',
        'Цикл',
        commonFailed ? 'Ошибка' : (cc.active ? (cc.pause ? 'Пауза' : 'Активен') : 'Стоп'),
        'Этап: ' + stageLabel(cc.stage),
        commonFailed ? '#d32f2f' : (cc.active ? (cc.pause ? '#ef6c00' : '#2e7d32') : '#90a4ae')
    ),
    buildSection(
        'conveyor',
        'Подводной',
        'Подача',
        !conveyorOnline ? 'Нет связи' : (conv.batch_ready ? 'Партия готова' : ((Number(conv.program_state || 0) > 0) ? 'Формирует партию' : 'Ожидание')),
        'Партия #' + Number(conv.batch_seq || 0) + ' | P1 ' + Number(conv.program_state || 0) + '/' + Number(conv.program_pass || 0),
        !conveyorOnline ? '#9e9e9e' : (conv.batch_ready ? '#2e7d32' : ((Number(conv.program_state || 0) > 0) ? '#1e88e5' : '#90a4ae'))
    ),
    buildSection(
        'manipulator',
        'Манипулятор',
        'Манип.',
        !manipOnline ? 'Нет связи' : (!!man.step7_ready ? 'Шаг 7' : ((Number(man.work_step || 0) > 0) ? ('Шаг ' + Number(man.work_step || 0)) : 'Ожидание')),
        'work_step=' + Number(man.work_step || 0) + ' | step7=' + (!!man.step7_ready ? 'да' : 'нет'),
        !manipOnline ? '#9e9e9e' : (!!man.step7_ready ? '#2e7d32' : ((Number(man.work_step || 0) > 0) ? '#1e88e5' : '#90a4ae'))
    ),
    buildSection(
        'otvod',
        'Отводной 2-ручейковый',
        'Отвод',
        otFailed ? 'Ошибка' : (ot.active ? 'В работе' : (!!ot.ready ? 'Готов' : 'Ожидание')),
        'step=' + Number(ot.step_done || 0) + ' | vfd=' + Number(ot.vfd_done || 0),
        otFailed ? '#d32f2f' : (ot.active ? '#1e88e5' : (!!ot.ready ? '#2e7d32' : '#90a4ae'))
    ),
    buildSection(
        'vfd',
        'Основной отводной / ПЧ',
        'ПЧ',
        !vfdOnline ? 'Нет связи' : ((Number(vfd.fault || 0) > 0) ? ('Авария ' + Number(vfd.fault || 0)) : (vfdRunHz > 0 ? (vfdRunHz.toFixed(1) + ' Гц') : 'Стоп')),
        'status=' + Number(vfd.status_word || 0) + ' | fault=' + Number(vfd.fault || 0),
        !vfdOnline ? '#9e9e9e' : ((Number(vfd.fault || 0) > 0) ? '#d32f2f' : (vfdRunHz > 0 ? '#1e88e5' : '#90a4ae'))
    ),
    buildSection(
        'seal',
        'Запайщик',
        'Запайка',
        !!seal.start_out ? 'Пуск' : (!!seal.done ? 'Завершен' : 'Ожидание'),
        'start=' + (!!seal.start_out ? 'ON' : 'OFF') + ' | done=' + (!!seal.done ? 'YES' : 'NO'),
        !!seal.start_out ? '#ef6c00' : (!!seal.done ? '#2e7d32' : '#90a4ae')
    )
];

msg.payload = { sections };
return msg;
